RARITIES = {row[1]: row[3] for row in CONTENT}
EVENT_WEIGHTS = {'chance': {'aquaPurify': 2, 'darkGame': 2, 'nzothWrath': 1},
                 'fortune': {'worldSeed': 2, 'endlessClouds': 1, 'pinkMiracle': 1}}


def assign(pool, all_candidates, old_candidates, old_probabilities):
    """输入旧精确概率与新增候选，仅从普通现金收入按比例让出本批事件额度。"""
    probabilities = {(kind, p['id']): value for (kind, p), value in zip(old_candidates, old_probabilities)}
    added = EVENT_WEIGHTS[pool]
    cost = sum(Fraction(v, 100) for v in added.values())
    income = [(kind, p) for kind, p in old_candidates if kind == 'income' and p['rarity'] != 'UR']
    budget = sum(probabilities[(kind, p['id'])] for kind, p in income)
    if budget <= cost:
        raise ValueError('普通现金事件配额不足')
    for kind, p in income:
        probabilities[(kind, p['id'])] *= (budget-cost)/budget
    for kind, p in all_candidates:
        if kind in added:
            probabilities[(kind, p['id'])] = Fraction(added[kind], 100)
    return all_candidates, [probabilities[(kind, p['id'])] for kind, p in all_candidates]
